import { saveFileRecord, getFileId } from '../db';

const DEMO_THUMBNAIL = "data:image/jpeg;base64,";

/**
 * Initializes the demo file by fetching it from the public folder
 * and saving it to the local database.
 * @returns {Promise<string|null>} The ID of the saved file record, or null if it failed.
 */
export const initDemoFile = async () => {
    try {
        const response = await fetch('/demo.pdf');
        if (!response.ok) {
            throw new Error(`Failed to fetch demo.pdf: ${response.status} ${response.statusText}`);
        }

        const blob = await response.blob();
        const file = new File([blob], 'demo.pdf', { type: 'application/pdf' });

        const fid = getFileId(file);

        await saveFileRecord({
            id: fid,
            name: file.name,
            blob: file,
            thumbnail: DEMO_THUMBNAIL,
            lastOpened: Date.now(),
            lastPage: 1,
            scale: 1.5,
            rotation: 0,
            darkMode: false,
            skipZones: []
        });

        console.log(`[Demo] demo.pdf initialized with ID: ${fid}`);
        return fid;
    } catch (error) {
        console.error('[Demo] Error initializing demo file:', error);
        return null;
    }
};
